import re, subprocess
path = r"F:\obsidian_notes\knowledge\TOEFL\词汇\AWL学术词汇表.md"
text = open(path, encoding='utf-8').read()
lines = text.split('\n')
errors = []

# 1. frontmatter identical to original (from git HEAD)
orig = subprocess.run(['git','show','HEAD:TOEFL/词汇/AWL学术词汇表.md'], capture_output=True, text=True, encoding='utf-8').stdout
fm_orig = orig.split('---',2)[1]
fm_new = text.split('---',2)[1]
print('frontmatter identical:', fm_orig == fm_new)
if fm_orig != fm_new: errors.append('frontmatter mismatch')

# 2. structure: 5 H2 headings, word counts per sublist
body = text.split('---',2)[2]
sections = re.split(r'^## ', body, flags=re.M)[1:]
print('num sections:', len(sections))
counts = {}
for s in sections:
    name = s.split('\n',1)[0].strip()
    words = [l for l in s.split('\n') if l.startswith('- ')]
    counts[name] = len(words)
print('counts:', counts)
if len(sections) != 5: errors.append('not 5 sections')
for k,v in counts.items():
    if v != 60: errors.append(f'{k} has {v} words')

# 3. every non-frontmatter non-heading line is one entry of format "- word pos meaning"
bad_lines = []
for l in lines:
    if not l.strip() or l.startswith('## ') or l.startswith('---') or l in ('tags:','  - English','Category:','  - 笔记'):
        continue
    if not re.match(r'^- [a-z]+ [a-z]+/?(?:[a-z]+)?\.? ', l) or l.count(' ') < 3 and '；' not in l:
        if not re.match(r'^- [a-z]+ [a-z.]+/[a-z.]+\. ', l) and not re.match(r'^- [a-z]+ [a-z]+\. [^ ]+；[a-z]+\. ', l):
            bad_lines.append(l)
print('malformed lines:', bad_lines)
if bad_lines: errors.append('malformed lines')

# 4. fixes checklist
checks = {
 'authority': '- authority n. 权威' in text,
 'proportion': '- proportion n. 比例' in text,
 'philosophy': '- philosophy n. 哲学' in text,
 'statistic': '- statistic n. 统计数据' in text,
 'no ascii ellipsis': '...' not in text,
 'consist fullwidth': '- consist v. 由…组成' in text,
}
print('fixes:', checks)
for k,v in checks.items():
    if not v: errors.append(f'fix missing: {k}')

# 5. no HTML, no double blank lines, no trailing blank lines
print('html present:', '<' in text)
if '<' in text: errors.append('html')
blank_runs = re.findall(r'\n\n\n+', text)
print('multi-blank-line runs:', blank_runs)
if blank_runs: errors.append('extra blank lines')
print('trailing blank:', text.endswith('\n\n'))
if text.endswith('\n\n'): errors.append('trailing blank')

# 6. word uniqueness
allwords = [l.split(' ',2)[1] for l in lines if l.startswith('- ')]
print('total words:', len(allwords), 'unique:', len(set(allwords)))
if len(allwords) != 300: errors.append('total != 300')

print('RESULT:', 'PASS' if not errors else 'FAIL: ' + '; '.join(errors))
PYEOF
